    let mut sum2: c_ulong = (adler >> 16) & 0xffff as c_ulong;
    adler &= 0xffff as c_ulong;

    if len == 1 as z_size_t {
        // SAFETY: the original function dereferences `buf` when `len == 1`, so callers must provide a valid readable byte pointer in this case.
        adler = adler.wrapping_add(unsafe { *buf } as c_ulong);
        if adler >= BASE as c_ulong {
            adler = adler.wrapping_sub(BASE as c_ulong);
        }
        sum2 = sum2.wrapping_add(adler);
        if sum2 >= BASE as c_ulong {
            sum2 = sum2.wrapping_sub(BASE as c_ulong);
        }
        return adler | ((sum2 as uLong) << 16);
    }

    if buf.is_null() {
        return 1 as uLong;
    }

    if len < 16 as z_size_t {
        while len != 0 {
            // SAFETY: `buf` is non-null here and the loop consumes exactly `len` bytes, matching the original pointer-walking semantics.
